class DotHero extends StatelessWidget {
  const DotHero({super.key, required this.config});

  final DotScreenConfig config;

  double _radiusFor(List<double> spectrum, double maxAllowed) {
    // When the title overlay is enabled, the available dot region can shrink
    // below [minDotSize]. In that case we allow the dot to get smaller so it
    // never intersects the title block or overflows its reserved region.
    if (maxAllowed <= 0.0) return 0.0;

    final minR = min(config.minDotSize, maxAllowed);
    final maxR = min(config.maxDotSize, maxAllowed);

    if (spectrum.isEmpty) return minR;

    var bass = 0.0;
    for (var i = 0; i < min(spectrum.length, 3); i++) {
      bass = max(bass, spectrum[i]);
    }
    final r = config.minDotSize +
        bass * bass * config.sensitivity * (config.maxDotSize - config.minDotSize);

    return r.clamp(minR, maxR);
  }

